def f(g, priority='bottom'):
    o=[[g[r][c] for c in range(6)] for r in range(3)]
    H=len(g)
    for r in range(3):
        for c in range(6):
            if g[r][c]!=0: continue
            cand=[g[H//4*1 + i*1 ][c] for i in range(H)] if False else None
            # candidate blocks: rows 3..H-1 split into bands of H//4=3 rows? use stride
            res=[]
            for band in range(1,H//3):
                v=g[band*3+r][c]
                if v!=0: res.append((band,v))
            if priority=='bottom':
                for b,v in sorted(res,reverse=True):
                    if b: o[r][c]=v
            elif priority=='top':
                for b,v in sorted(res):
                    if b: o[r][c]=v
            elif priority=='unique':
                uniq={v for _,v in res}
                if len(uniq)==1: o[r][c]=uniq.pop()
    return o

