G=load()
def f(g):
    o=[row[:] for row in g[:3]]
    # vertical: fill zeros adjacent below from bands1,2 (rows 3 and 6), spreading up
    H,W=6,3
    changed=True
    while changed:
        changed=False
        for r in range(2,-1,-1):
            for c in range(W):
                if o[r][c]!=0: continue
                if 0<=r+1<=2: continue
                src=g[r+1][c]
                if src!=0 and o[r+1][c]!=0:
                    o[r][c]=src; changed=True
    # horizontal flood in top band, blocked by original nonzero
    from collections import deque
    blocked=[[v!=0 for v in row] for row in g[:3]]
    seen=[[False]*W for _ in range(H)]
    dq=deque()
    for r in range(H):
        for c in range(W):
            if o[r][c]!=g[r][c]:
                seen[r][c]=True; dq.append((r,c))
    dirs=[(0,1),(0,-1)]
    while dq:
        r,c=dq.popleft()
        for dr,dc in dirs:
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and not blocked[nr][nc] and not seen[nr][nc] and o[nr][nc]!=g[nr][nc]:
                seen[nr][nc]=True; o[nr][nc]=o[r][c]; dq.append((nr,nc))
    return o
